import re

def create_crew(agents, tasks):
    agent_map = {a["name"]: a for a in agents}
    for task in tasks:
        assert task["agent"] in agent_map, f"Unknown agent: {task['agent']}"
    context = None
    outputs = []
    for task in tasks:
        agent = agent_map[task["agent"]]
        prompt = f"As a {agent['role']}, {task['description']}"
        if context:
            prompt += f"\nContext from previous: {context}"
        result = agent["execute"](prompt)
        outputs.append({"task": task["description"], "agent": task["agent"], "output": result})
        context = result
    return {"outputs": outputs, "final_output": context}
